      [
        [["c","Точный"],["d","Доминирующий"],["s","Охотный"],["i","Притягательный"]],
        [["i","Уравновешенный"],["c","Уступчивый"],["d","Идущий на риск"],["s","Услужливый"]],
        [["c","Осмотрительный"],["s","Добрососедский"],["d","Энергичный"],["i","Убедительный"]],
      ],
      [
        [["s","Уравновешенный"],["i","Мотивирующий"],["c","Щепетильный"],["d","Решительный"]],
        [["i","Уверенный"],["c","Готовый к сотрудничеству"],["s","Беззаботный"],["d","Аргументирующий"]],
        [["s","Сдержанный"],["d","Прямой"],["c","Строгий"],["i","Убедительный"]],
      ],
      [
        [["c","Застенчивый"],["d","Требовательный"],["s","Терпеливый"],["i","Очаровательный"]],
        [["d","Неугомонный"],["c","Дисциплинированный"],["i","Вдохновляющий"],["s","Внимательный"]],
        [["s","Обязательный"],["i","Оживленный"],["d","Решительный"],["c","Точный"]],
      ],
      [
        [["c","Добросовестный"],["i","Компанейский"],["s","Добрый"],["d","Уверенный в себе"]],
        [["c","Дипломатичный"],["d","Отважный"],["s","Сочувствующий"],["i","Оптимистичный"]],
        [["d","Настойчивый"],["i","Общительный"],["s","Постоянный"],["c","Организованный"]],
      ],
      [
        [["c","Соглашающийся"],["s","Владеющий собой"],["d","Шутливый"],["i","Настойчивый"]],
        [["i","Обаятельный"],["d","Позитивный"],["s","Снисходительный"],["c","Требовательный"]],
        [["i","Коммуникабельный"],["d","Смелый"],["c","Перфекционист"],["s","Сдержанный"]],
      ],
    ];
    const N_STEPS = STEPS.length;

    const el = (id) => document.getElementById(id);
    const modal = el("wizardmodal");
    const tabsEl = el("discTabs");
    const bodyEl = el("rootwizard");
    const progressEl = el("discProgress");
    const btnPrev = el("btnPrev");
    const btnNext = el("btnNext");
    const btnFinish = el("btnFinish");
    const resultsEl = el("results");

    let step = 0;

    /* ---------------- build tabs + panes ---------------- */
    function buildUI() {
      tabsEl.innerHTML = '';
      STEPS.forEach((_, s) => {
        const b = document.createElement('button');
        b.className = 'tab' + (s === 0 ? ' is-active' : '');
        b.type = 'button';
        b.role = 'tab';
        b.setAttribute('aria-selected', s === 0 ? 'true' : 'false');
        b.dataset.step = s;
        b.textContent = ordinal(s);
        b.addEventListener('click', () => goStep(s));
        tabsEl.appendChild(b);
      });

      bodyEl.innerHTML = '';
      STEPS.forEach((cards, s) => {
        const pane = document.createElement('div');
        pane.className = 'pane' + (s === 0 ? ' is-active' : '');
        pane.dataset.stepPane = s;
        pane.setAttribute('role', 'tabpanel');
        pane.innerHTML = `
          <div class="grid3">
          ${cards.map((card, ci) => `
            <div class="card">
              <h3>Я наиболее</h3>
              <ul class="list" data-card="${ci}"></ul>
              <h3 style="text-align:right;">Я наименее</h3>
            </div>
          `).join('')}
          </div>`;
        cards.forEach((card, ci) => {
          const list = pane.querySelector(`.list[data-card="${ci}"]`);
          card.forEach((it) => {
            const li = document.createElement('li');
            li.className = 'item';
            li.setAttribute('draggable', 'true');
            li.dataset.type = it[0];
            li.textContent = it[1];
            list.appendChild(li);
            // вставим бейдж типа
            const txt = document.createElement('span');
            txt.className = 'item__text'; txt.textContent = it[1];
            const badge = document.createElement('span');
            badge.className = 'item__type type-' + it[0]; badge.textContent = it[0].toUpperCase();
            li.textContent = ''; li.appendChild(txt); li.appendChild(badge);
          });
        });
        bodyEl.appendChild(pane);
      });
    }

    function ordinal(n) {
      const words = ['Первый','Второй','Третий','Четвертый','Пятый','Шестой','Седьмой','Восьмой'];
      return words[n] || ('Шаг ' + (n+1));
    }

    /* ---------------- drag & drop ---------------- */
    let dragSrc = null;
    function enableDnD(pane) {
      const list = pane.querySelector('.list');
      list.querySelectorAll('.item').forEach(item => {
        item.addEventListener('dragstart', onDragStart);
        item.addEventListener('dragend', onDragEnd);
        item.addEventListener('dragover', onDragOver);
        item.addEventListener('drop', onDrop);
        item.addEventListener('click', onItemTap);
      });
      list.addEventListener('dragover', onDragOver);
    }
    function onDragStart(e) {
      e.dataTransfer.effectAllowed = 'move';
      dragSrc = e.target;
      e.target.classList.add('dragging');
    }
    function onDragEnd() { dragSrc = null; }
    function onDragOver(e) {
      e.preventDefault();
      if (dragSrc && dragSrc.classList.contains('dragging')) {
        const li = e.target.closest('.item');
        if (li && li !== dragSrc) {
          const src = e.target.closest('.item');
          insertBefore(li, src);
        }
      }
    }
    function onDrop(e) {
      e.preventDefault();
      if (dragSrc && e.target.classList.contains('item')) {
        insertBefore(e.target, dragSrc);
      }
    }
    function insertBefore(target, src) {
      const before = target;
      if (src.classList.contains('dragging')) src.classList.remove('dragging');
      const after = target.nextSibling;
      if (after) src.insertBefore(after, src, src.previousSibling);
      else src.parentNode.insertBefore(src, src);
    }

    function onItemTap(e) {
      const li = e.target.closest('.item');
      if (!li) return;
      const list = li.parentNode;
      const items = Array.from(list.children);
      const i = items.indexOf(li);
      if (i === 0) return;
      const prev = items[i-1];
      list.insertBefore(prev, li);
    }

    /* ---------------- steps ---------------- */
    function goStep(s) {
      if (s < 0 || s >= N_STEPS) return;
      step = s;
      render();
    }
    function nextStep() {
      if (step >= N_STEPS - 1) return;
      goStep(step + 1);
    }
    function prevStep() {
      if (step === 0) return;
      goStep(step - 1);
    }

    function render() {
      bodyEl.querySelectorAll('.pane').forEach(p => p.classList.toggle('is-active', +p.dataset.stepPane === step));
      tabsEl.querySelectorAll('.tab').forEach((t, i) => {
        t.classList.toggle('is-active', i === step);
        t.setAttribute('aria-selected', i === step ? 'true' : 'false');
      });
      progressEl.style.width = ((step + 1) / N_STEPS * 100) + '%';
      btnFinish.hidden = !(step === N_STEPS - 1);
      btnNext.hidden = !(step === N_STEPS - 1);
      btnPrev.classList.toggle('is-disabled', step === 0);
      if (step === 0) {
        // enable dnd only on active pane
        enableDnD(bodyEl.querySelector('.pane.is-active'));
      } else {
        const active = bodyEl.querySelector('.pane.is-active');
        enableDnD(active);
      }
    }

    /* ---------------- results ---------------- */
    function computeScore() {
      const score = { d: 0, i: 0, s: 0, c: 0 };
      bodyEl.querySelectorAll('.pane').forEach(pane => {
        const items = Array.from(pane.querySelectorAll('.list .item'));
        items.forEach((item, idx) => {
          const rank = idx; // 0 = самый похожий
          const pts = 3 - rank; // 3,2,1,0
          const t = item.dataset.type;
          if (t && t in score) score[t] += pts;
        });
      });
      return score;
    }

    function showResults() {
      const s = computeScore();
      const d = s.d, i = s.i, st = s.s, c = s.c;
      el("rD").textContent = 'D:' + d;
      el("rI").textContent = 'I:' + i;
      el("rS").textContent = 'S:' + st;
      el("rC").textContent = 'C:' + c;
      const code = `D:${d}, I:${i}, S:${st}, C:${c}`;
      el("test_results").value = code;
      btnNext.hidden = true;
      btnPrev.hidden = true;
      btnFinish.hidden = true;
      progressEl.style.width = '100%';
      bodyEl.style.visibility = 'hidden';
      bodyEl.style.position = 'absolute';
      resultsEl.hidden = false;
      resultsEl.classList.remove('hidden');
    }

    function copyCode() {
      const inp = el("test_results");
      const btn = el("btnCopy");
      const text = inp.value;
      const doFallback = () => {
        inp.focus();
        try { inp.setSelectionRange(0, text.length); document.execCommand('copy'); } catch (_) {}
        inp.blur();
      };
      if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        navigator.clipboard.writeText(text).finally(() => flash(btn));
      } else {
        doFallback(); flash(btn);
      }
    }
    function flash(btn) {
      const def = btn.dataset.default ?? btn.textContent;
      btn.dataset.default = def;
      btn.textContent = 'Скопировано';
      btn.classList.add('is-copied');
      setTimeout(() => { btn.textContent = def; btn.classList.remove('is-copied'); }, 1500);
    }

    function closeModal() {
      modal.classList.remove('is-open');
      modal.setAttribute('aria-hidden', 'true');
      document.body.classList.remove('no-scroll');
      document.documentElement.classList.remove('no-scroll');
    }

    function openModal() {
      step = 0;
      modal.classList.add('is-open');
      modal.setAttribute('aria-hidden', 'false');
      document.body.classList.add('no-scroll');
      document.documentElement.classList.add('no-scroll');
    }

    /* ---------------- events ---------------- */
    document.getElementById("startBtn").addEventListener("click", openModal);
    btnNext.addEventListener("click", () => { if (step === N_STEPS - 1) { showResults(); } else { nextStep(); } });
    btnPrev.addEventListener("click", prevStep);
    btnFinish.addEventListener("click", showResults);
    el("btnCopy").addEventListener("click", copyCode);
    el("btnDone").addEventListener("click", closeModal);

    // close on overlay / esc
    document.getElementById("wizardmodal").querySelector("[data-disc-close]").addEventListener("click", closeModal);
    document.getElementById("wizardmodal").querySelector(".modal__close").addEventListener("click", closeModal);
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && modal.classList.contains("is-open")) closeModal();
    });

    buildUI();
    render();
  })();
  </script>
</body>
</html>"
